INSERT INTO public.content_schedule (title, channel_label, scheduled_date, status, brand, body, cta, post_type, notes) SELECT 'Cross-contact and the allergen requirement most kitchens miss', 'LinkedIn', '2026-09-28', 'planned', 'EvidLY', 'THEME: Cross-contact and the allergen requirement most kitchens miss
