INSERT INTO public.content_schedule (title, channel_label, scheduled_date, status, brand, body, cta, post_type, notes) SELECT 'The same violation means different things in different counties.', 'Facebook', '2026-08-25', 'drafted', 'ScoreTable', 'A temperature finding might cost a small deduction in one county and be classified as major in the next one over — with a re-inspection and a public posting.

