INSERT INTO public.content_schedule (title, channel_label, scheduled_date, status, brand, body, cta, post_type, notes) SELECT 'The date matters as much as the result.', 'Facebook', '2026-09-10', 'drafted', 'ScoreTable', 'An inspection result without its date is a claim about the present made from evidence about the past.

